// Build one item per topic to generate today (cap to keep cost + review load sane).
const b = $input.first().json;
const MAX = Number($env.CONTENT_TOPICS_PER_DAY || 2);
const topics = (b.suggestedTopics || []).slice(0, MAX);
const ctx = {
  categories: (b.categories || []).filter((c) => c !== 'company-update' && c !== 'product-update'),
  recentTitles: (b.recentTitles || b.recentNews || []),
  services: b.services || [],
  sectors: b.sectors || [],
};
return topics.map((topic) => ({ json: { topic, ...ctx } }));

