// Parse the model's JSON (it returns ONLY the object). Skip on any problem —
// never throw, so one bad topic doesn't kill the run.
out = [];
for (const item of $input.all()) {
  try {
    const txt = item.json?.content?.[0]?.text || '';
    const json = JSON.parse(txt.trim().replace(/^```(json)?|```$/g, '').trim());
    if (json && json.title && json.body && json.summary && json.category) out.push({ json });
  } catch (e) {
    out.push({ json: { _skip: true, error: String(e) } });
  }
}
return out.filter((i) => !i.json._skip);
